using System;
using System.Collections.Generic;
using HarmonyLib;
using UnityEngine;

namespace VerdantsAscent.Water.Core
{
    /// <summary>
    /// Live runtime overrides for properties on Valheim's Custom/SkyboxProcedural
    /// material. Built to A/B-test which property controls the visible
    /// "horizon-haze band" the user reports at distance — the band is NOT
    /// generated by FiresWater (we verified no horizon math in the shader);
    /// it's the procedural-skybox blending its <c>_SkyTint</c> upper
    /// hemisphere with <c>_GroundColor</c> lower hemisphere through the
    /// <c>_AtmosphereThickness</c>-driven scattering integral, possibly
    /// further modulated by the <c>_FogHeightMin</c>/<c>_FogHeightMax</c>
    /// height-fog band.
    ///
    /// USAGE: Flip <see cref="Enabled"/> via ConfigManager
    /// (FiresWater.SkyboxOverride). With defaults (mul=1, offsets=0, blend=0)
    /// behavior is identical to vanilla — enabling alone changes nothing.
    /// Then tweak each property via the BepInEx ConfigurationManager sliders
    /// in-game and watch the horizon band. Whichever property visibly affects
    /// the band is the responsible one.
    ///
    /// LIFETIME: EnvMan rewrites <c>RenderSettings.skybox</c> on env
    /// transitions (sometimes mid-frame). The driver re-applies overrides
    /// EVERY LateUpdate so a fresh skybox material can't strand our values.
    /// Originals are captured per-material-InstanceID on first sight and
    /// restored on Enabled=false so the user can rollback without restarting.
    ///
    /// SAFETY: We only override materials whose shader is the supported
    /// procedural-skybox name. Custom env skyboxes with other shaders pass
    /// through untouched.
    /// </summary>
    public static class FiresSkyboxDriver
    {
        // Supports BOTH vanilla Custom/SkyboxProcedural AND our replacement
        // Custom/FiresSkyboxAurora. Both honor the same property contract.
        public const string SupportedShader = "Custom/SkyboxProcedural";
        public const string SupportedShaderAurora = "Custom/FiresSkyboxAurora";

        // Master switch — controlled from ConfigManager.configFiresSkyboxOverride
        // via FiresTossinShade.ApplyFiresWaterConfig.
        public static bool Enabled = false;

        // While disabled we restore the captured originals ONCE, then stop writing — otherwise
        // re-writing them every frame fights EnvMan (which also drives the procedural skybox each
        // frame), and the two alternating writes flash the sky rapidly. Reset when re-enabled.
        private static bool s_restoredWhileDisabled;

        // Blended rain-cloud amount off the live SetEnv env (fed by FiresSkyboxEnvLightRide's
        // postfix). RAMPS through env transitions like everything else vanilla blends —
        // GetCurrentEnvironment().m_rainCloudAlpha would JUMP at the env switch (hard cut).
        internal static float LiveRainCloudAlpha;

        // Time-eased aurora gate 0..1. The raw auroraActive check flips BINARY at the night
        // boundary — snapping _GroundColor to the aurora cycle / _FogHeightMin to the glow value
        // in one frame. Easing it over AuroraGateSeconds matches vanilla's timed env crossfades.
        public  static float AuroraGateSeconds = 2.5f;
        private static float s_auroraBlend;

        // ---- Tunable overrides (multiplier-style; default to no-op 1.0) ----
        // Each multiplies the captured original value so EnvMan's per-env
        // tuning still drives the visible result; the user's slider just
        // scales it. Defaults of 1.0 produce vanilla behavior.

        public static float AtmosphereThicknessMultiplier = 1.0f;
        public static float ExposureMultiplier = 1.0f;
        // How much the SKY itself dims in a full storm (0 = no change, 1 = black).
        // Drives the procedural skybox _Exposure down by the env's rain-cloud amount,
        // so the bright daytime sky goes dark/overcast in rain + thunderstorms.
        public static float StormSkyDarken = 0.6f;
        public static float StarExposureMultiplier = 1.0f;
        public static float SunSizeMultiplier = 1.0f;
        public static float MoonSizeMultiplier = 1.0f;

        // Offset-style for fog height (additive on top of captured value)
        public static float FogHeightMinOffset = 0f;
        public static float FogHeightMaxOffset = 0f;

        // Directional-light intensity multipliers — applied to whatever
        // Unity light is currently active (sun during day, moon at night).
        // The driver doesn't try to distinguish them; it scales the active
        // light by SunLightMultiplier × (IsNight ? MoonLightMultiplier : 1).
        // Captures original Light.intensity on first sight per-instance.
        public static float SunLightMultiplier = 1.0f;
        public static float MoonLightMultiplier = 1.0f;

        /// <summary>
        /// Lerp factor from captured <c>_GroundColor</c> toward captured
        /// <c>_SkyTint</c>. 0.0 = unchanged (vanilla). 1.0 = ground color
        /// exactly matches sky tint (kills the horizon-color discontinuity
        /// between upper and lower hemispheres).
        /// </summary>
        public static float GroundColorBlendToSky = 0f;

        // ---- Aurora glow (Path A) --------------------------------------------
        // Animates _GroundColor through a green→cyan→purple gradient and
        // forces _AtmosphereThickness low at night. When the player looks
        // toward the horizon the procedural skybox's atmospheric scattering
        // makes the colored ground hemisphere bleed up — looks like an
        // aurora-borealis backdrop glow. Real curtain ribbons come from the
        // separate FiresAurora shader (Path B); this is the static backdrop.
        public static bool AuroraGlowEnabled = false;
        public static float AuroraGlowIntensity = 1.0f;
        public static float AuroraGlowSpeed = 0.05f;
        public static float AuroraGlowAtmosphereMul = 0.25f;
        public static bool AuroraGlowNightOnly = true;
        // While aurora glow is active, override _FogHeightMin to this Y
        // value (typically below the horizon line). The procedural skybox
        // uses _FogHeightMin/_FogHeightMax as a height-based fog band
        // that masks the GroundColor when the fog band sits at/above the
        // visible horizon — that's why the colored hemisphere doesn't
        // bleed up until the user drags FogHeightMin down manually. Push
        // it well below sea level (Y=30) so the colored hemisphere
        // reaches the horizon line and the aurora glow becomes visible
        // without the user touching the skybox-override sliders.
        public static float AuroraGlowFogHeightMin = -100f;

        // RETIRED 2026-05-31: AuroraGlowFogHeightMax and AuroraGlowSkyTintAmount
        // were attempts to make the skybox itself "dome" the aurora glow over
        // the player. They only ever painted a thin horizon strip / faint sky
        // wash — the procedural skybox is a uniform sphere with no spatial
        // bias and can't represent a north-facing dome shape. The geometric
        // FiresAurora curtain hemisphere is the only path that wraps overhead.
        // Skybox driver now stays out of _FogHeightMax / _SkyTint entirely
        // and limits itself to the horizon-glow color cycle on _GroundColor.

        // The aurora color palette cycles through these stops over time.
        // Tuned for classic green-dominant aurora with cyan/purple accents.
        // PUBLIC so FiresAuroraOverlay can pull the same palette and stay
        // visually in lockstep with the skybox horizon glow — user feedback
        // 2026-05-31 was that the overhead dome held a static color while
        // only the horizon band cycled. Same source = same animation.
        // Physically-accurate aurora color stops. Real auroras are
        // OVERWHELMINGLY green-dominant — atomic oxygen at 100-150 km emits
        // 557.7 nm green far brighter than any other auroral emission. The
        // rarer reds (O 630 nm, >200 km) and violets/blues (N2+ 391/428 nm,
        // <100 km) only appear during strong geomagnetic activity. So this
        // palette spends most of its cycle in green tones, briefly visits
        // the rarer pink/magenta and violet boundaries, and loops back.
        public static readonly Color[] s_auroraStops = new[]
        {
            new Color(0.10f, 1.00f, 0.40f, 1f),  // pure aurora green (557.7 nm O)
            new Color(0.20f, 0.95f, 0.55f, 1f),  // bright green
            new Color(0.30f, 0.85f, 0.75f, 1f),  // cyan-green transition
            new Color(0.85f, 0.45f, 0.75f, 1f),  // pink/magenta (O 630 + N2+ mix)
            new Color(0.30f, 0.35f, 1.00f, 1f),  // deep violet-blue (N2+ 391/428 nm)
            new Color(0.20f, 0.95f, 0.55f, 1f),  // bright green again
            new Color(0.10f, 1.00f, 0.40f, 1f),  // back to dominant green (loops)
        };

        /// <summary>
        /// Walks the aurora color palette over time. <paramref name="t"/> is
        /// a free-running time value (typically <c>Time.unscaledTime *
        /// AuroraGlowSpeed</c>). Wraps so the cycle is continuous. Same
        /// helper the skybox horizon-glow uses internally; exposed for
        /// <see cref="FiresAuroraOverlay"/> so the overhead dome animates
        /// in sync with the horizon glow.
        /// </summary>
        public static Color SampleAuroraStops(float t)
        {
            return SampleStops(s_auroraStops, t);
        }

        // ---- Internals -------------------------------------------------------

        private struct Original
        {
            public float AtmosphereThickness;
            public float FogHeightMin;
            public float FogHeightMax;
            public float Exposure;
            public float StarExposure;
            public float SunSize;
            public float MoonSize;
            public Color GroundColor;
            public Color SkyTint;
            public bool HasAtmosphereThickness;
            public bool HasFogHeightMin;
            public bool HasFogHeightMax;
            public bool HasExposure;
            public bool HasStarExposure;
            public bool HasSunSize;
            public bool HasMoonSize;
            public bool HasGroundColor;
            public bool HasSkyTint;

            // What WE last wrote per property (valid once Wrote). Used by
            // RefreshBaselineFromExternalWrites: a property no longer holding our
            // last-written value means EnvMan blended it since (dawn/dusk, env
            // crossfade) — adopt the live value as the new baseline so the
            // multipliers scale EnvMan's CURRENT sky, never a stale capture.
            public bool  Wrote;
            public float WAtmosphereThickness;
            public float WFogHeightMin;
            public float WFogHeightMax;
            public float WExposure;
            public float WStarExposure;
            public float WSunSize;
            public float WMoonSize;
            public Color WGroundColor;
            public Color WSkyTint;
        }

        // Keyed by Material.GetInstanceID(). EnvMan may share a single
        // skybox material across multiple envs OR instantiate one per env —
        // either way, instance-id keying captures each baseline correctly.
        private static readonly Dictionary<int, Original> s_originals
            = new Dictionary<int, Original>();

        private static readonly int Prop_AtmosphereThickness
            = Shader.PropertyToID("_AtmosphereThickness");
        private static readonly int Prop_Exposure
            = Shader.PropertyToID("_Exposure");
        private static readonly int Prop_StarExposure
            = Shader.PropertyToID("_StarExposure");
        private static readonly int Prop_SunSize
            = Shader.PropertyToID("_SunSize");
        private static readonly int Prop_MoonSize
            = Shader.PropertyToID("_MoonSize");
        private static readonly int Prop_FogHeightMin
            = Shader.PropertyToID("_FogHeightMin");
        private static readonly int Prop_FogHeightMax
            = Shader.PropertyToID("_FogHeightMax");
        private static readonly int Prop_GroundColor
            = Shader.PropertyToID("_GroundColor");
        private static readonly int Prop_SkyTint
            = Shader.PropertyToID("_SkyTint");

        /// <summary>
        /// Per-frame entry point. Reads <see cref="RenderSettings.skybox"/>,
        /// captures originals on first sight, then writes either originals
        /// (Enabled=false) or override values (Enabled=true). No-op if the
        /// skybox is null or uses an unsupported shader.
        /// </summary>
        public static void ApplyToActiveSkybox()
        {
            var sky = RenderSettings.skybox;
            if (sky == null || sky.shader == null) return;
            // Accept both vanilla Custom/SkyboxProcedural AND our aurora
            // replacement Custom/FiresSkyboxAurora — both honor the same
            // property contract so the multiplier writes work either way.
            if (sky.shader.name != SupportedShader && sky.shader.name != SupportedShaderAurora) return;

            CaptureIfNeeded(sky);
            int skyId = sky.GetInstanceID();
            var orig = s_originals[skyId];

            // EnvMan blends these same properties during dawn/dusk and env crossfades. Any
            // property that no longer holds OUR last-written value was rewritten by EnvMan
            // since — refresh its baseline to the live value so the overrides below scale
            // EnvMan's CURRENT sky. Without this, re-stamping the stale first-sight capture
            // every frame pins the sky mid-transition and fights EnvMan (the same alternating
            // -writes disease as the disabled-path flash, just hidden by write order).
            RefreshBaselineFromExternalWrites(sky, ref orig);

            if (!Enabled)
            {
                // Restore the captured originals ONCE, then STOP writing — EnvMan drives the
                // procedural skybox every frame, so re-writing our (stale) originals every frame
                // fights it and the two alternating writes FLASH the sky rapidly. Restoring once
                // undoes our overrides; EnvMan then owns the material again with no fight.
                if (!s_restoredWhileDisabled)
                {
                    if (orig.HasAtmosphereThickness)
                        sky.SetFloat(Prop_AtmosphereThickness, orig.AtmosphereThickness);
                    if (orig.HasFogHeightMin)
                        sky.SetFloat(Prop_FogHeightMin, orig.FogHeightMin);
                    if (orig.HasFogHeightMax)
                        sky.SetFloat(Prop_FogHeightMax, orig.FogHeightMax);
                    if (orig.HasGroundColor)
                        sky.SetColor(Prop_GroundColor, orig.GroundColor);
                    if (orig.HasSkyTint)
                        sky.SetColor(Prop_SkyTint, orig.SkyTint);
                    s_restoredWhileDisabled = true;
                }
                return;
            }
            s_restoredWhileDisabled = false;   // re-enabled — allow a fresh one-shot restore next disable

            // Aurora gating — the raw check flips binary at the night boundary, so EASE a 0..1
            // blend over AuroraGateSeconds (vanilla-style timed transition) and lerp every
            // aurora-dependent value by it: no hard cut in _GroundColor/_FogHeightMin/atmosphere
            // at dusk/dawn.
            bool auroraTarget = AuroraGlowEnabled
                && AuroraGlowIntensity > 0.001f
                && (!AuroraGlowNightOnly || IsNight());
            s_auroraBlend = Mathf.MoveTowards(s_auroraBlend, auroraTarget ? 1f : 0f,
                Time.deltaTime / Mathf.Max(0.05f, AuroraGateSeconds));
            float aBlend = s_auroraBlend;
            bool auroraActive = aBlend > 0.001f;

            float atmMul = Mathf.Lerp(AtmosphereThicknessMultiplier, AuroraGlowAtmosphereMul, aBlend);

            if (orig.HasAtmosphereThickness)
            {
                float v = Mathf.Max(0f, orig.AtmosphereThickness * atmMul);
                sky.SetFloat(Prop_AtmosphereThickness, v);
                orig.WAtmosphereThickness = v;
            }

            // New multiplier-style overrides: Exposure / StarExposure /
            // SunSize / MoonSize. Default 1.0 = vanilla unchanged so
            // user opts in to changes by moving sliders.
            // Storm darkens the sky: drop the skybox exposure by the env's rain-cloud
            // amount so a downpour/thunderstorm reads as a dim overcast (EnvMan dims
            // the scene light + ambient, but nothing was dimming the SKY itself).
            // Blended rain (LiveRainCloudAlpha, fed by the SetEnv postfix) so the darken RAMPS
            // through the env crossfade like vanilla — GetCurrentEnvironment()'s static value
            // would jump at the env switch and step the sky exposure.
            float stormMul = 1f;
            if (StormSkyDarken > 0.001f)
                stormMul = Mathf.Lerp(1f, 1f - Mathf.Clamp01(StormSkyDarken), Mathf.Clamp01(LiveRainCloudAlpha));

            if (orig.HasExposure)
            {
                float v = orig.Exposure * ExposureMultiplier * stormMul;
                sky.SetFloat(Prop_Exposure, v);
                orig.WExposure = v;
            }
            if (orig.HasStarExposure)
            {
                float v = orig.StarExposure * StarExposureMultiplier * (1f - FiresSkyboxAurora.DayFactor());   // 0.3.159: no stars by day
                sky.SetFloat(Prop_StarExposure, v);
                orig.WStarExposure = v;
            }
            if (orig.HasSunSize)
            {
                float v = orig.SunSize * SunSizeMultiplier * FiresSunHaze.SunSizeMultiplier;
                sky.SetFloat(Prop_SunSize, v);
                orig.WSunSize = v;
            }
            if (orig.HasMoonSize)
            {
                float v = orig.MoonSize * MoonSizeMultiplier;
                sky.SetFloat(Prop_MoonSize, v);
                orig.WMoonSize = v;
            }

            // Directional light multipliers are applied in FiresSkyboxEnvLightRide
            // (a postfix on EnvMan.SetEnv) so they SCALE the live per-frame intensity
            // EnvMan just wrote, rather than freezing a stale first-sight capture here.
            // While aurora glow is active, override FogHeightMin to the
            // aurora-specific value (pushed below sea level) so the
            // colored hemisphere isn't masked by the height-fog band.
            // The user previously had to drag this slider down manually
            // to see the glow — automate it here.
            if (orig.HasFogHeightMin)
            {
                float v = Mathf.Lerp(orig.FogHeightMin + FogHeightMinOffset,
                                     AuroraGlowFogHeightMin, aBlend);
                sky.SetFloat(Prop_FogHeightMin, v);
                orig.WFogHeightMin = v;
            }
            if (orig.HasFogHeightMax)
            {
                float v = orig.FogHeightMax + FogHeightMaxOffset;
                sky.SetFloat(Prop_FogHeightMax, v);
                orig.WFogHeightMax = v;
            }

            // Always keep _SkyTint at the captured value. The geometric
            // FiresAurora curtain dome handles overhead wrap; trying to
            // wash it from the skybox here only produced a faint uniform
            // upper-hemisphere tint with no spatial bias (couldn't fade
            // out south, couldn't intensify north).
            if (orig.HasSkyTint)
            {
                sky.SetColor(Prop_SkyTint, orig.SkyTint);
                orig.WSkyTint = orig.SkyTint;
            }

            if (orig.HasGroundColor)
            {
                // Normal (non-aurora) horizon colour.
                Color normal = orig.HasSkyTint
                    ? Color.Lerp(orig.GroundColor, orig.SkyTint, Mathf.Clamp01(GroundColorBlendToSky))
                    : orig.GroundColor;

                Color target = normal;
                if (auroraActive)
                {
                    // Horizon glow color cycle. The geometric dome handles
                    // wrap-overhead; this paints the horizon band where
                    // the dome edge meets the sea so the two visually
                    // continue into one another rather than reading as
                    // separate effects. Eased in/out by aBlend so the glow
                    // FADES up at dusk instead of snapping on.
                    float t = Time.unscaledTime * AuroraGlowSpeed;
                    Color cycled = SampleStops(s_auroraStops, t);
                    float pulse = 0.6f + 0.4f * Mathf.Sin(Time.unscaledTime * 0.35f);
                    target = Color.Lerp(normal, cycled * (AuroraGlowIntensity * pulse), aBlend);
                }
                sky.SetColor(Prop_GroundColor, target);
                orig.WGroundColor = target;
            }

            // Persist the refreshed baselines + written values for next frame's dirty check.
            orig.Wrote = true;
            s_originals[skyId] = orig;
        }

        // Per-property: if the material no longer holds the value WE last wrote, EnvMan (or
        // another system) wrote it since — adopt the live value as the new baseline. Values
        // still holding our write are left alone (re-reading them would compound multipliers).
        private static void RefreshBaselineFromExternalWrites(Material sky, ref Original orig)
        {
            if (!orig.Wrote) return;
            if (orig.HasAtmosphereThickness)
            { float c = sky.GetFloat(Prop_AtmosphereThickness); if (Differs(c, orig.WAtmosphereThickness)) orig.AtmosphereThickness = c; }
            if (orig.HasFogHeightMin)
            { float c = sky.GetFloat(Prop_FogHeightMin); if (Differs(c, orig.WFogHeightMin)) orig.FogHeightMin = c; }
            if (orig.HasFogHeightMax)
            { float c = sky.GetFloat(Prop_FogHeightMax); if (Differs(c, orig.WFogHeightMax)) orig.FogHeightMax = c; }
            if (orig.HasExposure)
            { float c = sky.GetFloat(Prop_Exposure); if (Differs(c, orig.WExposure)) orig.Exposure = c; }
            if (orig.HasStarExposure)
            { float c = sky.GetFloat(Prop_StarExposure); if (Differs(c, orig.WStarExposure)) orig.StarExposure = c; }
            if (orig.HasSunSize)
            { float c = sky.GetFloat(Prop_SunSize); if (Differs(c, orig.WSunSize)) orig.SunSize = c; }
            if (orig.HasMoonSize)
            { float c = sky.GetFloat(Prop_MoonSize); if (Differs(c, orig.WMoonSize)) orig.MoonSize = c; }
            if (orig.HasGroundColor)
            { Color c = sky.GetColor(Prop_GroundColor); if (Differs(c, orig.WGroundColor)) orig.GroundColor = c; }
            if (orig.HasSkyTint)
            { Color c = sky.GetColor(Prop_SkyTint); if (Differs(c, orig.WSkyTint)) orig.SkyTint = c; }
        }

        private static bool Differs(float a, float b)
            => Mathf.Abs(a - b) > Mathf.Max(1e-4f, Mathf.Abs(b) * 1e-3f);

        private static bool Differs(Color a, Color b)
            => Mathf.Abs(a.r - b.r) + Mathf.Abs(a.g - b.g)
             + Mathf.Abs(a.b - b.b) + Mathf.Abs(a.a - b.a) > 0.004f;

        // Linear walk through the color stops, wrapping at the last entry.
        // stops[0] at t=0, stops[N-1] at t=1, wrap to stops[0] at t=N (etc).
        private static Color SampleStops(Color[] stops, float t)
        {
            int n = stops.Length;
            if (n == 0) return Color.black;
            if (n == 1) return stops[0];
            float wrapped = Mathf.Repeat(t, n - 1);
            int idx = (int)Mathf.Floor(wrapped);
            float frac = wrapped - idx;
            return Color.Lerp(stops[idx], stops[Mathf.Min(idx + 1, n - 1)], frac);
        }

        // Vanilla day/night: EnvMan.IsNight() is STATIC. Guard the instance
        // anyway because EnvMan.IsNight reads instance state internally and
        // returns false safely if instance isn't ready.
        internal static bool IsNight()
        {
            try { return EnvMan.instance != null && EnvMan.IsNight(); }
            catch { return false; }
        }

        private static void CaptureIfNeeded(Material sky)
        {
            int id = sky.GetInstanceID();
            if (s_originals.ContainsKey(id)) return;

            var orig = new Original
            {
                HasAtmosphereThickness = sky.HasProperty(Prop_AtmosphereThickness),
                HasFogHeightMin = sky.HasProperty(Prop_FogHeightMin),
                HasFogHeightMax = sky.HasProperty(Prop_FogHeightMax),
                HasExposure = sky.HasProperty(Prop_Exposure),
                HasStarExposure = sky.HasProperty(Prop_StarExposure),
                HasSunSize = sky.HasProperty(Prop_SunSize),
                HasMoonSize = sky.HasProperty(Prop_MoonSize),
                HasGroundColor = sky.HasProperty(Prop_GroundColor),
                HasSkyTint = sky.HasProperty(Prop_SkyTint),
            };
            if (orig.HasAtmosphereThickness) orig.AtmosphereThickness = sky.GetFloat(Prop_AtmosphereThickness);
            if (orig.HasFogHeightMin) orig.FogHeightMin = sky.GetFloat(Prop_FogHeightMin);
            if (orig.HasFogHeightMax) orig.FogHeightMax = sky.GetFloat(Prop_FogHeightMax);
            if (orig.HasExposure) orig.Exposure = sky.GetFloat(Prop_Exposure);
            if (orig.HasStarExposure) orig.StarExposure = sky.GetFloat(Prop_StarExposure);
            if (orig.HasSunSize) orig.SunSize = sky.GetFloat(Prop_SunSize);
            if (orig.HasMoonSize) orig.MoonSize = sky.GetFloat(Prop_MoonSize);
            if (orig.HasGroundColor) orig.GroundColor = sky.GetColor(Prop_GroundColor);
            if (orig.HasSkyTint) orig.SkyTint = sky.GetColor(Prop_SkyTint);

            s_originals[id] = orig;
            Debug.Log(
                $"[FiresSkyboxDriver] Captured originals for skybox '{sky.name}' " +
                $"(instId={id}): atmThick={orig.AtmosphereThickness:F3}, " +
                $"fogH=[{orig.FogHeightMin:F1}, {orig.FogHeightMax:F1}], " +
                $"groundCol={orig.GroundColor}, skyTint={orig.SkyTint}");
        }
    }

    /// <summary>
    /// Per-frame applier — attach exactly once to a persistent GameObject
    /// (FiresTossinShade.RootObject is fine). LateUpdate so the active
    /// skybox material reflects any env-transition rewrite EnvMan made
    /// during the frame.
    /// </summary>
    public class FiresSkyboxDriverComponent : MonoBehaviour
    {
        // Throttle for warning-spam if the skybox material is misconfigured.
        // The driver gets called every frame and Unity property writes
        // shouldn't throw — but defensive code is cheap.
        private int m_lastWarnFrame = -10000;
        private const int WARN_INTERVAL_FRAMES = 600;

        private void LateUpdate()
        {
            try
            {
                FiresSkyboxDriver.ApplyToActiveSkybox();
            }
            catch (Exception ex)
            {
                if (Time.frameCount - m_lastWarnFrame > WARN_INTERVAL_FRAMES)
                {
                    m_lastWarnFrame = Time.frameCount;
                    Debug.LogWarning(
                        $"[FiresSkyboxDriver] ApplyToActiveSkybox failed: {ex.Message}");
                }
            }
        }
    }

    /// <summary>
    /// EnvMan rewrites the directional sun/moon light intensity FRESH every frame from its
    /// day/night blend (EnvMan.SetEnv: <c>m_dirLight.intensity = env.day*dayInt + env.night*nightInt</c>).
    /// The FiresSkybox override's Sun/Moon light multipliers therefore have to SCALE that live
    /// value — the old path captured the intensity once and forced captured×mul each frame, which
    /// froze the light at one time of day the moment the override turned on (visible even at mul=1).
    /// Postfixing SetEnv applies the multiplier right after EnvMan's own write, so it rides every
    /// time-of-day / weather change and can't compound (EnvMan re-assigns the baseline each call).
    /// Vanilla parity: hook exactly where the engine drives the value, then layer on top.
    /// </summary>
    [HarmonyPatch(typeof(EnvMan), "SetEnv")]
    internal static class FiresSkyboxEnvLightRide
    {
        private static void Postfix(EnvSetup env, float dayInt, float nightInt, float morningInt, float eveningInt,
                                    Light ___m_dirLight)
        {
            // Blended rain for the storm sky-darken: SetEnv receives the already-crossfaded env,
            // so its m_rainCloudAlpha RAMPS through the transition exactly like vanilla —
            // unlike GetCurrentEnvironment(), whose static value JUMPS at the env switch.
            if (env != null) FiresSkyboxDriver.LiveRainCloudAlpha = env.m_rainCloudAlpha;

            FiresSunHaze.UpdateFromEnv(env, dayInt, nightInt, morningInt, eveningInt);

            if (!FiresSkyboxDriver.Enabled || ___m_dirLight == null) return;
            float mul = FiresSkyboxDriver.IsNight()
                ? FiresSkyboxDriver.MoonLightMultiplier
                : FiresSkyboxDriver.SunLightMultiplier;
            if (mul != 1f) ___m_dirLight.intensity *= mul;
        }
    }
}
